To rotate the door around its edge using the hinge as the pivot, you need to adjust the door's position relative to the hinge before applying the rotation.

This can be achieved by first determining the offset vector between the hinge and the door's center. Then, apply the same rotation to this offset vector to correctly position the door relative to the hinge.

Here's the revised implementation:
```kotlin
private _update(deltaTime: number): void {
  this.time += deltaTime;

  const desiredVec3 = this.doorState ? this.doorClosedVec3 : this.doorOpenVec3;

  // Determine the offset vector between the hinge and the door's center.
  const doorCenter = this.door?.position.get() || Vec3.zero;
  const hingePosition = this.props.Hinge.position.get();
  const offsetVector = doorCenter.subtract(hingePosition);

  // Compute the rotation quaternion based on time and desiredVec3.
  const sinTime = Math.sin(this.time);
  const sinVec3 = new Vec3(0, sinTime * 90, 0);
  const sinQuaternion = Quaternion.fromEuler(sinVec3);

  // Rotate the offset vector by the same rotation as the door to determine the correct position of the door relative to the hinge.
  const rotatedOffsetVector = sinQuaternion.rotate(offsetVector);

  // Adjust the door's position relative to the hinge, then rotate it around the hinge using the sinQuaternion.
  this.door?.moveRelativeTo(this.props.Hinge, rotatedOffsetVector, Space.World);
  this.door?.rotateRelativeTo(this.props.Hinge, sinQuaternion, Space.World);
}
