```javascript
let codeSpans = [];

function randomizeCodeColors() {
  console.log("Looking for new code elements...");

  // Check for new code elements every 2 seconds
  setInterval(() => {
    // Find all code elements that are children of a pre element and not already being colored
    const codeElements = document.querySelectorAll("pre code:not([data-randomize-colors])");

    // Loop through each new code element
    codeElements.forEach(code => {
      console.log(`Found new code element: ${code}`);

      // Find all span elements within the code element
      const spanElements = code.querySelectorAll("span");
      const limitedSpanElements = Array.from(spanElements).slice(0, 1000);
      codeSpans.push([code, ...limitedSpanElements]);

      // Mark the code element and its spans as already being colored
      code.dataset.randomizeColors = true;
      limitedSpanElements.forEach(span => {
        span.dataset.randomizeColors = true;
      });
    });

    // Remove any code elements and spans that are no longer present
    codeSpans = codeSpans.filter(([code, ...spans]) => {
      if (!document.contains(code)) {
        console.log(`Removed code element: ${code}`);
        return false;
      }
