To implement support for "doubly-indirect" blocks in xv6, follow these steps:

1. Modify `param.h` to increase the file system size:
```c
#define FSSIZE 20000 // size of file system in blocks
```
2. Change `NDIRECT` in `fs.h` to 11 to accommodate the new doubly-indirect block and update `MAXFILE` to reflect the new capacity:
```c
#define NDIRECT 11
#define NINDIRECT (BSIZE / sizeof(uint))
#define MAXFILE (NDIRECT + NINDIRECT + NINDIRECT*NINDIRECT)
```
3. Update the `inode` structure in `file.h` to align the size of `addrs[]` with the new `NDIRECT` value:
```c
struct inode {
  ...
  uint addrs[NDIRECT+2];   // Data block addresses
};
```
4. Modify the `bmap()` function in `fs.c` to incorporate the doubly-indirect block:
```c
static uint
bmap(struct inode *ip, uint bn)
{
  uint addr, *a, *b;
  struct buf *bp, *bp2;

  if(bn < NDIRECT){
    if((addr = ip->addrs[bn]) == 0)
      ip->addrs[bn] = addr = balloc(ip->dev);
    return addr;
  }
  bn -= NDIRECT;

  if(bn < NINDIRECT){
    // singly indirect block
    if((addr = ip->addrs[NDIRECT]) == 0)
      ip->addrs[NDIRECT] = addr = balloc(ip->dev);
    bp = bread(ip->dev, addr);
    a = (uint*)bp->data;
    if((addr = a[bn]) == 0){
      a[bn] = addr = balloc(ip->dev);
      log_write(bp);
    }
    brelse(bp);
    return addr;
  }

  bn -= NINDIRECT;

  if(bn < NINDIRECT*NINDIRECT){
    // doubly indirect block
    if((addr = ip->addrs[NDIRECT+1]) == 0)
      ip->addrs[NDIRECT+1] = addr = balloc(ip->dev);
    bp = bread(ip->dev, addr);
    a = (uint*)bp->data;
    if((addr = a[bn / NINDIRECT]) == 0){
      a[bn / NINDIRECT] = addr = balloc(ip->dev);
      log_write(bp);
    }
    brelse(bp);
    bp2 = bread(ip->dev, addr);
    b = (uint*)bp2->data;
    if((addr = b[bn % NINDIRECT]) == 0){
      b[bn % NINDIRECT] = addr = balloc(ip->dev);
      log_write(bp2);
    }
    brelse(bp2);
    return addr;
  }

  panic("bmap: out of range");
}
```
