        perror("getifaddrs");
        return "";
    }

    for (ifa = ifaddr; ifa != nullptr; ifa = ifa->ifa_next) {
        if (ifa->ifa_addr == nullptr) {
            continue;
        }

        if ((ifa->ifa_flags & IFF_UP) && (ifa->ifa_flags & IFF_RUNNING) && !(ifa->ifa_flags & IFF_LOOPBACK)) {
            int family = ifa->ifa_addr->sa_family;
            if (family == AF_INET || family == AF_INET6) {
                void* tmp_addr_ptr = nullptr;
                if (family == AF_INET) {
                    tmp_addr_ptr = &((struct sockaddr_in *) ifa->ifa_addr)->sin_addr;
                } else {
                    tmp_addr_ptr = &((struct sockaddr_in6 *) ifa->ifa_addr)->sin6_addr;
                }
                inet_ntop(family, tmp_addr_ptr, gateway_ip, sizeof(gateway_ip));
                break;
            }
        }
    }
    freeifaddrs(ifaddr);
    return gateway_ip;
}

#endif

int main() {
    std::string gateway_ip = get_gateway_ip();
    if (!gateway_ip.empty()) {
        std::cout << "Gateway IP: " << gateway_ip << std::endl;
    } else {
        std::cout << "Unable to retrieve gateway IP" << std::endl;
    }
    return 0;
}
