#include <gmp.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

static gmp_randstate_t state;

void randstate_init(uint64_t seed) {
    gmp_randinit_mt(state);
    gmp_randseed_ui(state, seed);
    srandom(seed);
}

void randstate_clear(void) {
    gmp_randclear(state);
}

void pow_mod(mpz_t out, mpz_t base, mpz_t exponent, mpz_t modulus) {
    mpz_powm(out, base, exponent, modulus);
}

bool is_prime(mpz_t n, uint64_t iters) {
    return mpz_probab_prime_p(n, iters);
}

void make_prime(mpz_t p, uint64_t bits, uint64_t iters) {
    while (1) {
        mpz_rrandomb(p, state, bits);
        mpz_setbit(p, bits - 1);
        mpz_setbit(p, 0);
        if (is_prime(p, iters)) {
            break;
        }
    }
}

void mod_inverse(mpz_t i, mpz_t a, mpz_t n) {
    if (mpz_invert(i, a, n) == 0) {
        mpz_set_ui(i, 0);
    }
}

void ss_make_pub(mpz_t p, mpz_t q, mpz_t n, uint64_t nbits, uint64_t iters) {
    uint64_t pbits = random() % (2 * nbits / 5 - nbits / 5) + nbits / 5;
    uint64_t qbits = nbits - 2 * pbits;

    make_prime(p, pbits, iters);
    make_prime(q, qbits, iters);

    mpz_mul(n, p, q);
}

void ss_write_pub(mpz_t n, char username[], FILE *pbfile) {
