  { id: 1, content: 'apple' },
  { id: 2, content: 'banana' },
  { id: 3, content: 'cherry' },
  { id: 4, content: 'durian' },
];

const searchTerm = 'ppl';

const filteredObjects = searchObjects(searchTerm, objects);

console.log(filteredObjects); // Output: [{ id: 1, content: 'apple' }]
```

In this example, the `searchTerm` 'ppl' matches the 'apple' object, so the filtered array contains only that object.

