```csharp
using FlaUI.Core;
using FlaUI.Core.AutomationElements;
using FlaUI.UIA3;
using System;
using System.Collections.Generic;
using System.Threading;

class Program
{
    static UIA3Automation automation = new UIA3Automation();
    static AutomationElement window;
    static List<string> parsedText = new List<string>();
    static object lockObject = new object();
    static bool isParsing = false;

    static void Main(string[] args)
    {
        window = automation.GetDesktop().FindFirstChild(cf => cf.ByName("Notepad"));

        var thread = new Thread(() =>
        {
            while (true)
            {
                ParseUITree();
                Thread.Sleep(1000);
            }
        });
        thread.IsBackground = true;
        thread.Start();

        Console.WriteLine("Press 'q' to quit");
        while (true)
        {
            var input = Console.ReadKey(true);
            if (input.KeyChar == 'q')
            {
                break;
            }

            lock (lockObject)
            {
                foreach (var text in parsedText)
                {
                    Console.WriteLine(text);
                }
            }
        }
    }

    static void ParseUITree()
    {
        try
        {
            if (isParsing)
            {
                return;
            }

            isParsing = true;

            var textElement = window.FindFirstChild(cf => cf.ByControlType(FlaUI.Core.Definitions.ControlType.Document));
            if (textElement == null)
            {
                Console.WriteLine("Text element not found");
                return;
            }

            var text = textElement.GetText();

            lock (lockObject)
            {
                parsedText.Add(text);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error parsing UI tree: " + ex.Message);
        }
        finally
        {
            isParsing = false;
        }
    }
}
```

In this example, a `List<string>` is used to store parsed text, and a `lockObject` is employed to synchronize access to this list. A `bool` flag named `isParsing` ensures that the `ParseUITree` method is not re-entered while parsing is ongoing, which helps prevent race conditions. The program uses a `try`/`catch` block to manage exceptions during parsing, and the `finally` block ensures `isParsing` is reset to false, preventing potential infinite loops in case of an exception. This approach demonstrates handling race conditions when parsing UI elements in the background with FlaUI, ensuring safe access to parsed elements by other program components.

