The following C# code demonstrates how to traverse a directory and its subdirectories, collect all the full file paths of zero-byte files, and then insert them into a SQL Server table named `ZeroByteFiles` in a database called `ExternalData` in bulk at the end of the process:

```csharp
using System;
using System.Data.SqlClient;
using System.IO;
using System.Collections.Generic;

class Program
{
    static void Main(string[] args)
    {
        string rootDirectory = @"C:\example";
        string connectionString = "Server=localhost;Database=ExternalData;Trusted_Connection=True;";
        List<string> zeroByteFiles = new List<string>();
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();
            TraverseDirectory(rootDirectory, zeroByteFiles);
            InsertInBulk(zeroByteFiles, connection);
            connection.Close();
        }
    }
    static void TraverseDirectory(string directory, List<string> zeroByteFiles)
    {
        foreach (string file in Directory.EnumerateFiles(directory))
        {
            FileInfo fileInfo = new FileInfo(file);
            if (fileInfo.Length == 0)
            {
                zeroByteFiles.Add(fileInfo.FullName);
            }
        }

        foreach (string subdirectory in Directory.EnumerateDirectories(directory))
        {
            TraverseDirectory(subdirectory, zeroByteFiles);
        }
    }
    static void InsertInBulk(List<string> zeroByteFiles, SqlConnection connection)
    {
        using (SqlCommand command = new SqlCommand("INSERT INTO ZeroByteFiles (FilePath) VALUES (@FilePath)", connection))
        {
            command.Parameters.Add("@FilePath", System.Data.SqlDbType.NVarChar);
            foreach (string file in zeroByteFiles)
            {
                command.Parameters["@FilePath"].Value = file;
                command.ExecuteNonQuery();
            }
        }
    }
}
```

In this example, the `rootDirectory` variable specifies the starting directory for traversal. The `connectionString` variable contains the connection string for the SQL Server database where the list of zero-byte files will be stored. The `TraverseDirectory` method is used recursively to navigate the directory tree, utilizing `Directory.EnumerateFiles` and `Directory.EnumerateDirectories` to access files and subdirectories. If a file's length is 0, its full path is added to the `zeroByteFiles` list. Once all subdirectories are traversed, the `InsertInBulk` method inserts all files from the list into the `ZeroByteFiles` table in the `ExternalData` database using `SqlCommand` and `SqlParameter`.

