            params.add(request.getStartDate());
        }

        if (request.getEndDate() != null) {
            if (!params.isEmpty()) {
                sql += "AND ";
            }
            sql += "CREATE_TS <= ? ";
            params.add(request.getEndDate());
        }

        if (request.getOperationType() != null) {
            if (!params.isEmpty()) {
                sql += "AND ";
            }
            sql += "OPERATION_NAME = ? ";
            params.add(request.getOperationType());
        }

        return jdbcTemplate.query(sql, params.toArray(), new SMTReportResponseMapper());
    }

    private static class SMTReportResponseMapper implements RowMapper<SMTReportResponse> {
        @Override
        public SMTReportResponse mapRow(ResultSet rs, int rowNum) throws SQLException {
            SMTReportResponse response = new SMTReportResponse();
            response.setTransactionId(rs.getLong("TRANSACTION_ID"));
            response.setFunctionName(rs.getString("FUNCTION_NAME"));
            response.setOperationName(rs.getString("OPERATION_NAME"));
            response.setCreateUserId(rs.getString("CREATE_USER_ID"));
            response.setCreateTs(rs.getTimestamp("CREATE_TS").toLocalDateTime());
            response.setLastUpdateUser(rs.getString("LAST_UPDATE_USER"));
            response.setLastUpdateTs(rs.getTimestamp("LAST_UPDATE_TS").toLocalDateTime());
            response.setLineId(rs.getLong("LINE_ID"));
            response.setCableAccountNumber(rs.getString("CABLE_ACCOUNT_NUMBER"));
            return response;
        }
    }

}
```

In this implementation, Spring's `JdbcTemplate` is used to query the database. The SQL query is constructed dynamically based on the user input, with conditions added for each non-null field. The query results are mapped to `SMTReportResponse` objects using a `RowMapper`. The implementation supports various input scenarios:

1. If only the start date is provided, the query returns rows where CREATE_TS is on or after the start date.
2. If only the end date is provided, the query returns rows where CREATE_TS is on or before the end date.
3. If only the operation type is provided, the query returns rows where OPERATION_NAME matches the operation type.
4. If both start and end dates are provided, the query returns rows where CREATE_TS is between these dates.
5. If start date and operation type are provided, the query returns rows where CREATE_TS is on or after the start date and OPERATION_NAME matches.
6. If end date and operation type are provided, the query returns rows where CREATE_TS is on or before the end date and OPERATION_NAME matches.
7. If all three fields are provided, the query returns rows where CREATE_TS is between the start and end dates and OPERATION_NAME matches.

The implementation assumes input dates are compatible with the CREATE_TS column format. If not, date parsing may be necessary.

