public IEnumerator GetUserEmail(string accessToken)
{
    // Create the API request.
    string apiEndpoint = "https://api.twitch.tv/helix/users";
    UnityWebRequest request = UnityWebRequest.Get(apiEndpoint);
    request.SetRequestHeader("Authorization", "Bearer " + accessToken);

    // Send the API request and wait for the response.
    yield return request.SendWebRequest();

    // Handle the API response.
    if (request.result == UnityWebRequest.Result.Success)
    {
        // Parse the API response.
        string jsonResponse = request.downloadHandler.text;
        var json = JsonUtility.FromJson<TwitchUserResponse>(jsonResponse);

        // Log the user's email address.
        Debug.Log("User email: " + json.data[0].email);
    }
    else
    {
        // Log the API error.
        Debug.LogError(request.error);
    }
}

