```javascript
const {BigQuery} = require('@google-cloud/bigquery');

async function exportData() {
  // Create a client
  const bigquery = new BigQuery();

  // Set up the parameters for the export job
  const projectId = 'my-project-id';
  const datasetId = 'my-dataset-id';
  const tableId = 'my-table-id';
  const bucketUri = 'gs://my-bucket/exported-data/';

  // Configure the export job
  const options = {
    configuration: {
      extract: {
        sourceTable: {
          projectId: projectId,
          datasetId: datasetId,
          tableId: tableId,
        },
        destinationUris: [bucketUri],
        compression: 'NONE',
      },
    },
  };

  // Start the export job
  const [job] = await bigquery
    .createJob(options)
    .then(results => {
      const job = results[0];
      console.log(`Job ${job.id} started.`);
      return job.promise();
    })
    .catch(err => {
      console.error('ERROR:', err);
    });

  // Check the status of the job
  console.log(`Job ${job.id} completed.`);
}

exportData();
```

This script initiates an export job that transfers the specified table from BigQuery to the designated Cloud Storage bucket. The code waits for the job to finish and then outputs the job's status upon completion.

