    // Accept an incoming connection
    printf("Waiting for incoming connections...\n");
    c = sizeof(struct sockaddr_in);
    while ((client_sock = accept(socket_desc, (struct sockaddr *)&client, (socklen_t *)&c)))
    {
        printf("Connection accepted\n");

        // Receive a message from client
        while ((read_size = recv(client_sock, client_message, 2000, 0)) > 0)
        {
            // Process the message
            printf("Received message: %s\n", client_message);

            // Send an ACK in response
            if (send(client_sock, ack_message, strlen(ack_message), 0) < 0)
            {
                printf("Error sending ACK message");
            }
        }

        if (read_size == 0)
        {
            printf("Client disconnected\n");
        }
        else if (read_size == -1)
        {
            perror("recv failed");
        }
    }

    return 0;
}
```

In this example, a variable `ack_message` is defined to contain the string "ACK". After receiving a message from the client, the server processes it and sends an ACK message back using the `send()` function. If there is an error in sending the ACK message, an error message is printed. In practical applications, a custom protocol might be used to represent different types of messages.

