Here's how you can modify the code to place the cURL calls in a separate class:

```cpp
#include <curl/curl.h>
#include <iostream>
#include <string>

class CurlHandler {
 public:
  CurlHandler() {
    curl_ = curl_easy_init();
  }

  ~CurlHandler() {
    if (curl_) {
      curl_easy_cleanup(curl_);
    }
  }

  std::string performRequest(const std::string& url, const std::string& authHeader) {
    if (!curl_) {
      std::cerr << "Failed to initialize cURL" << std::endl;
      return "";
    }

    curl_easy_setopt(curl_, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl_, CURLOPT_FOLLOWLOCATION, 1L);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, authHeader.c_str());
    curl_easy_setopt(curl_, CURLOPT_HTTPHEADER, headers);

    std::string response;
    curl_easy_setopt(curl_, CURLOPT_WRITEFUNCTION, curlCallback);
    curl_easy_setopt(curl_, CURLOPT_WRITEDATA, &response);

    CURLcode res = curl_easy_perform(curl_);
    if (res != CURLE_OK) {
      std::cerr << "cURL error: " << curl_easy_strerror(res) << std::endl;
      return "";
    }

    long httpCode;
    curl_easy_getinfo(curl_, CURLINFO_RESPONSE_CODE, &httpCode);
    if (httpCode != 200) {
      std::cerr << "API error: " << response << std::endl;
      return "";
    }

    return response;
  }

 private:
  static size_t curlCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    std::string *data = static_cast<std::string *>(userp);
    data->append(static_cast<char *>(contents), realsize);
    return realsize;
  }

  CURL *curl_;
};

class RobinhoodAPI {
 public:
  RobinhoodAPI(const std::string& accessToken) : accessToken_(accessToken), curlHandler_() {}

  std::string getCurrentPrice(const std::string& symbol) {
    std::string endpoint = "https://api.robinhood.com/quotes/?symbols=" + symbol;
    std::string authHeader = "Authorization: Token " + accessToken_;
    std::string response = curlHandler_.performRequest(endpoint, authHeader);

    if (response.empty()) {
      return "";
    }

    rapidjson::Document doc;
    doc.Parse(response.c_str());
    if (doc.HasParseError()) {
      std::cerr << "JSON parsing error: " << rapidjson::GetParseError_En(doc.GetParseError()) << std::endl;
      return "";
    }

    const rapidjson::Value& results = doc["results"];
    if (!results.IsArray() || results.Empty()) {
      std::cerr << "API error: invalid response" << std::endl;
      return "";
    }
    const rapidjson::Value& result = results[0];
    if (!result.IsObject() || !result.HasMember("last_trade_price")) {
      std::cerr << "API error: invalid response" << std::endl;
      return "";
    }
    const rapidjson::Value& price = result["last_trade_price"];
    if (!price.IsString()) {
      std::cerr << "API error: invalid response" << std::endl;
      return "";
    }

    return price.GetString();
  }

 private:
  std::string accessToken_;
  CurlHandler curlHandler_;
};
```

