#include <string>

using namespace std;

int countOccurrences(string str, string word) {
    int count = 0;
    stack<char> s;
    int len = str.length();
    int wordLen = word.length();
    for (int i = 0; i < len; i++) {
        s.push(str[i]);
        if (s.size() > wordLen) {
            s.pop();
        }
