```c++
#include <iostream>
#include <list>
#include <utility>

template <typename K, typename V>
class HashMap {
private:
    static const int ARRAY_SIZE = 101;  // Prime number
    std::list<std::pair<K, V>> table[ARRAY_SIZE];

    int hash(const K& key) const {
        // Hash function for string keys
        int hash = 0;
        for (char c : key) {
            hash = (hash * 31 + c) % ARRAY_SIZE;
        }
        return hash;
    }

public:
    void put(const K& key, const V& value) {
        int index = hash(key);
        for (auto& pair : table[index]) {
            if (pair.first == key) {
                pair.second = value;
                return;
            }
        }
        table[index].emplace_back(key, value);
    }

    V get(const K& key) const {
        int index = hash(key);
        for (const auto& pair : table[index]) {
            if (pair.first == key) {
                return pair.second;
            }
        }
        throw std::out_of_range("Key not found.");
    }

    void remove(const K& key) {
        int index = hash(key);
        auto it = table[index].begin();
        while (it != table[index].end()) {
            if (it->first == key) {
                it = table[index].erase(it);
                return;
            }
            ++it;
        }
        throw std::out_of_range("Key not found.");
    }
};
```

In this implementation, the `HashMap` class template uses two type parameters `K` and `V` for the key and value types. The `table` is an array of linked lists, where each element in the array is a head node of a linked list storing key-value pairs with the same hash code.

The `hash()` function computes a hash code for string keys, returning an integer between 0 and `ARRAY_SIZE - 1`.

The `put()` method inserts a key-value pair into the hash map. It calculates the hash code for the key and checks if the key already exists in the linked list at the corresponding index. If it does, it updates the value; otherwise, it adds a new node with the key-value pair.

The `get()` method retrieves a value from the hash map by computing the hash code for the key and searching the linked list at the corresponding index. If the key is found, it returns the value; if not, it throws an exception.

The `remove()` method deletes a key-value pair from the hash map by finding the node with the matching key in the linked list at the corresponding index. If found, it removes the node; if not, it throws an exception.

This implementation is basic and may not handle all scenarios efficiently, such as collision handling or resizing the array when the number of key-value pairs grows significantly.

