```csharp
using UnityEngine;
using UnityEngine.AI;

public class GuardAI : MonoBehaviour
{
    public Transform player; // Reference to the player object
    public Transform[] patrolPoints; // Array of patrol points
    private int currentPatrolPoint = 0; // Index of the current patrol point
    private NavMeshAgent agent; // Reference to the NavMeshAgent component
    public float viewAngle = 110f; // The guard's view angle
    public float viewDistance = 5f; // The guard's view distance
    public LayerMask viewMask; // The layers that the guard can see

    void Start()
    {
        agent = GetComponent<NavMeshAgent>();
        currentPatrolPoint = Random.Range(0, patrolPoints.Length);
        agent.destination = patrolPoints[currentPatrolPoint].position;
    }

    void Update()
    {
        // Check if the agent has reached the current patrol point
        if (agent.remainingDistance < 0.5f)
        {
            currentPatrolPoint = Random.Range(0, patrolPoints.Length);
            agent.destination = patrolPoints[currentPatrolPoint].position;
        }

        // Check if the player is within the guard's view
        if (CanSeePlayer())
        {
            agent.destination = player.position;
        }
    }

    bool CanSeePlayer()
    {
        // Calculate the direction to the player
        Vector3 direction = player.position - transform.position;

        // Check if the player is within the view angle
        if (Vector3.Angle(direction, transform.forward) < viewAngle / 2)
        {
            // Check if the player is within the view distance
            if (Physics.Raycast(transform.position, direction, out RaycastHit hit, viewDistance, viewMask))
            {
                // Check if the raycast hit the player
                if (hit.collider.gameObject == player.gameObject)
                {
                    return true;
                }
            }
        }

        return false;
    }
}
```

In this modified script, the guard object has a line of sight system and patrols between randomly selected points.

\subsection{Explainability in NLP}
\label{section:explanability}
We start by introducing the notion of explainability in NLP, discussing its definition and importance. To prepare for our analysis of model explanation methods in subsequent sections, we will also present a set of properties to categorize different methods, as well as several common design principles.

\subsubsection{What Is Explainability}\leavevmode\newline
\label{section:explainability\_definition}

According to the Cambridge Dictionary, an \textit{explanation} is: 
\begin{quote}
 The details or reasons that someone gives to make something clear or easy to understand \cite{walter\_cambridge\_2008}.
\end{quote}
In the context of Machine Learning, \textit{explainability} (also referred to as \textit{interpretability}\footnote{Despite their subtle distinctions in some previous literature, we use the terms interchangeably.}) is the extent to which the internal mechanics of a model can be presented in understandable terms to a human \cite{lipton\_mythos\_2017, murdoch\_definitions\_2019, barredo\_arrieta\_explainable\_2020}. 

Despite this intuitive notion, explainability has no established technical definition in the community, which results in numerous papers ``wielding the term in a quasi-scientific way'', essentially referring to different concepts \cite{lipton\_mythos\_2017, doshi-velez\_towards\_2017, miller\_explanation\_2018, murdoch\_definitions\_2019}. We argue that the confusion mainly lies in the interpretation of two key concepts in the above definition: (a) what are the \textbf{``internal mechanics''}? and (b) who is the \textbf{``human''}?\\

